results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


PLAN4 = {"task_name": "Put the beaker on the hotplate", "segments": [
    {"type": "navigation", "description": "Go to the beaker", "completion_criteria": "At the beaker", "target": "the beaker"},
    {"type": "manipulation", "description": "Pick up the beaker", "completion_criteria": "The beaker is held", "target": None, "primitive": "pick", "objects": [{"phrase": "the beaker", "role": "manipulated"}]},
    {"type": "navigation", "description": "Go to the hotplate", "completion_criteria": "At the hotplate", "target": "the hotplate"},
    {"type": "manipulation", "description": "Place the beaker on the hotplate", "completion_criteria": "The beaker is on the hotplate and the gripper is open", "target": None, "primitive": "place",
     "objects": [{"phrase": "the beaker", "role": "manipulated"}, {"phrase": "the hotplate", "role": "destination"}]}]}


class FakeCheck:
    """A stand-in for the full check: the first `fail` calls fail (home clearance), the rest pass."""

    def __init__(self, fail):
        self.calls, self.fail = [], fail

    def check(self, stance, points):
        self.calls.append(stance)
        ok = len(self.calls) > self.fail
        return {"ok": ok, "failed": [] if ok else ["home_clearance"], "reason": "" if ok else "fake: home_clearance 10 mm"}

    place_calls = []
    theta, window = 35, True                      # what place_theta_at gives (class attributes; section 6 changes them)

    def place_theta_at(self, stance, points):
        """The place angle search at one stance (M184): the fake gives `theta` or, with window False, no window."""
        FakeCheck.place_calls.append((tuple(stance), [p.get("path") for p in points]))
        if not FakeCheck.window:
            return {"theta_deg": None, "window_deg": None, "width_deg": 0, "windows": [], "reason": "no place angle window: fake"}
        return {"theta_deg": FakeCheck.theta, "window_deg": [FakeCheck.theta - 20, FakeCheck.theta + 20], "width_deg": 40, "windows": [], "reason": ""}


def world(beaker_xy=None, hotplate_xy=None, extra=()):
    w = WorldModel([StaticTaskSource()])
    w.refresh(0.0)
    if beaker_xy is not None:
        w.get("beaker").position[:2] = beaker_xy
    if hotplate_xy is not None:
        w.get("hotplate").position[:2] = hotplate_xy
    for e in extra:
        w.upsert(e)
    return w


def pillar(xy, height, radius=0.04):
    return Entry("pillar", "pillar", ("pillar",), "object", np.array([*xy, 0.0]), None, {"height": height, "supported_by": "bench", "shape": {"kind": "cylinder", "radius": radius}})


def main():
    from src import full_check  # noqa: F401
    sim = load_task()
    m, d = sim.model, sim.data
    maps = bs.load_maps("data/reach_map", sides=("left",))
    ctx = make_context(m, d, maps)
    tagged = postprocess(PLAN4, False, say=lambda *_: None)
    quiet = lambda *_: None
    cfg = copy.deepcopy(BENCH_STANCE_CFG)

    print("\n1. the test scene")
    sel = select_bench_stance(tagged, world(), TASK_CFG, ctx, cfg, say=quiet)
    rep = sel["report"]
    ch = rep.get("chosen")
    print(f"    chosen {ch}; runs {[(r['steps'], r['nav'], np.round(r['stance']['xy'], 3).tolist(), r['stance']['q']) for r in rep['runs']]}; null nav {rep['null_nav']}; TASK_CFG {TASK_CFG['staging_xy']} {TASK_CFG['pedestal_q']}")
    check("one run holds both steps and the second navigation step is null", sel["ok"] and len(rep["runs"]) == 1 and rep["runs"][0]["steps"] == [1, 3] and rep["null_nav"] == [2] and rep["runs"][0]["nav"] == [0], f"{rep['runs'][0]['steps'] if rep['runs'] else None}")
    check("the stance covers both objects (counts above zero)", all(v > 0 for v in rep["runs"][0]["counts"].values()), f"{rep['runs'][0]['counts']}")
    check("the returned TASK_CFG has the chosen stance, the plan keeps its steps", sel["task_cfg"]["staging_xy"] == tuple(rep["runs"][0]["stance"]["xy"]) and len(sel["plan"]["segments"]) == 4)
    base_stance = rep["runs"][0]["stance"]

    print("\n2. two objects far apart")
    w = world(hotplate_xy=(-0.9, 0.66))
    sel = select_bench_stance(tagged, w, TASK_CFG, ctx, cfg, say=quiet)
    rep = sel["report"]
    print(f"    ok {sel['ok']}; runs {[(r['steps'], r['nav'], np.round(r['stance']['xy'], 3).tolist()) for r in rep['runs']]}; tried {[(t.get('steps'), t.get('covered')) for t in rep['tried']]}")
    check("k=2 fails (the best stance covers one object), k=1 passes for each: two runs, each with its own stance", sel["ok"] and len(rep["runs"]) == 2 and [r["steps"] for r in rep["runs"]] == [[1], [3]] and rep["tried"] and rep["tried"][0]["steps"] == [1, 3] and len(rep["tried"][0]["covered"]) == 1)
    check("two navigation steps, both move (none is null)", [r["nav"] for r in rep["runs"]] == [[0], [2]] and rep["null_nav"] == [])
    check("the two stances are far apart", math.hypot(rep["runs"][0]["stance"]["xy"][0] - rep["runs"][1]["stance"]["xy"][0], rep["runs"][0]["stance"]["xy"][1] - rep["runs"][1]["stance"]["xy"][1]) > 1.0)

    print("\n3. an obstacle that blocks at a low pedestal height and clears at a high one")
    pick_only = {"task_name": "pick", "segments": PLAN4["segments"][:2]}
    tg1 = postprocess(pick_only, False, say=quiet)
    base = select_bench_stance(tg1, world(), TASK_CFG, ctx, cfg, say=quiet)
    q0 = base["report"]["runs"][0]["stance"]["q"]
    print(f"    without the obstacle: stance {np.round(base['report']['runs'][0]['stance']['xy'], 3).tolist()} pedestal {q0}")
    found = None
    for hgt in (0.10, 0.15, 0.20, 0.25, 0.30):
        w = world(extra=[pillar((1.0, 0.80), hgt)])
        s2 = select_bench_stance(tg1, w, TASK_CFG, ctx, cfg, say=quiet)
        if s2["ok"]:
            q1 = s2["report"]["runs"][0]["stance"]["q"]
            print(f"    pillar {hgt:.2f} m tall at (1.0, 0.80): stance {np.round(s2['report']['runs'][0]['stance']['xy'], 3).tolist()} pedestal {q1}")
            if q1 > q0 + 0.005 and found is None:
                found = (hgt, q1)
    check("with the obstacle the algorithm picks a higher pedestal than without", found is not None, f"{found} against {q0}")

    print("\n4. all approaches blocked")
    w = world(extra=[pillar((1.0, 0.70), 1.2, radius=0.06)])
    s3 = select_bench_stance(tg1, w, TASK_CFG, ctx, cfg, say=quiet)
    print(f"    stop: {s3['stop']}")
    check("the selection stops and names the blocker", (not s3["ok"]) and s3["stop"] and s3["stop"].startswith("no stance covers any of the objects") and "blocked by ['pillar']" in s3["stop"])

    print("\n5. the full check fails the top pick")
    fc = FakeCheck(fail=1)
    s4 = select_bench_stance(tagged, world(), TASK_CFG, ctx, cfg, full_check=fc, say=quiet)
    r4 = s4["report"]["runs"][0]
    check("the next ranked stance is used", s4["ok"] and len(fc.calls) == 2 and [t["full_check_ok"] for t in r4["full_check"]] == [False, True] and tuple(r4["stance"]["xy"]) == tuple(r4["full_check"][1]["xy"]) and r4["full_check"][0]["xy"] != r4["full_check"][1]["xy"], f"{len(fc.calls)} calls")
    fc = FakeCheck(fail=99)
    s5 = select_bench_stance(tagged, world(), TASK_CFG, ctx, cfg, full_check=fc, say=quiet)
    check("every tried stance failing stops with the criterion and the stances (the best and 3 more)", (not s5["ok"]) and len(fc.calls) == 4 and s5["stop"].startswith("no stance passed the full check:") and s5["stop"].count("home_clearance") >= 4, f"{len(fc.calls)} calls: {s5['stop'][:160]}")

    print("\n6. navigation off")
    cfg_off = {**cfg, "navigation": False}
    s6 = select_bench_stance(tagged, world(), TASK_CFG, ctx, cfg_off, say=quiet)
    check("the test scene is served from TASK_CFG's stance: kept, no stop", s6["ok"] and s6["task_cfg"]["staging_xy"] == tuple(TASK_CFG["staging_xy"]) and s6["task_cfg"]["pedestal_q"] == TASK_CFG["pedestal_q"], f"{s6['stop']}")
    # M184 (Oct 26): navigation off no longer means "the skill turns the hand by 0": the place angle is searched at TASK_CFG's stance (the same window search) and goes to the place step.
    # Before: this section only checked that the stance is kept. Now it also checks that the search ran at that stance, on the place points, and that its angle is in the plan.
    s6b = select_bench_stance(tagged, world(), TASK_CFG, ctx, cfg_off, full_check=FakeCheck(fail=0), say=quiet)
    place_seg = [g for g in s6b["plan"]["segments"] if g.get("primitive") == "place"]
    st0 = FakeCheck.place_calls[-1][0] if FakeCheck.place_calls else None
    check("navigation off: the place angle is searched at TASK_CFG's stance and the plan's place step carries it (no default 0)",
          s6b["ok"] and len(FakeCheck.place_calls) == 1 and st0[:2] == tuple(TASK_CFG["staging_xy"]) and abs(st0[3] - TASK_CFG["pedestal_q"]) < 1e-9 and all(p == "carry" or p in ("setdown", "back") for p in FakeCheck.place_calls[-1][1])
          and place_seg and all(g.get("place_theta_deg") == 35.0 for g in place_seg), f"calls {FakeCheck.place_calls}, place steps {[g.get('place_theta_deg') for g in place_seg]}")
    FakeCheck.window = False
    s6c = select_bench_stance(tagged, world(), TASK_CFG, ctx, cfg_off, full_check=FakeCheck(fail=0), say=quiet)
    FakeCheck.window = True
    check("navigation off, no window at the stance: the selection stops with 'no place angle window'", (not s6c["ok"]) and s6c["stop"].startswith("no place angle window"), f"{s6c['stop']}")
    s7 = select_bench_stance(tagged, world(beaker_xy=(1.45, 0.66), hotplate_xy=(1.25, 0.66)), TASK_CFG, ctx, cfg_off, say=quiet)
    print(f"    stop: {s7['stop']}")
    check("objects TASK_CFG's stance does not serve stop with 'needs navigation on' and the two stances", (not s7["ok"]) and s7["stop"].startswith("needs navigation on: the current stance is (0.765, 1.085)") and "the best stance" in s7["stop"])

    print("\n7. a post in the creep-in lane")
    rg = ctx.rg
    tg = base_stance
    x0, y0 = tg["xy"]
    L = ctx.furniture
    layers = {k: v.copy() for k, v in L.layers.items()}
    back = TASK_CFG["staging_approach_back_m"]
    fp = rg["footprint"]
    # the post stands in the lane behind the stance, outside the footprint at the stance but inside the swept corridor
    rear = float(np.abs(fp[:, 0]).max())
    px, py = x0, y0 + rear + 0.10
    ix, iy = int(round((px - L.origin[0]) / L.res)), int(round((py - L.origin[1]) / L.res))
    layers["base"][iy - 3:iy + 4, ix - 3:ix + 4] = True
    L2 = FurnitureMap(layers, L.origin, L.res, L.arm_radius)
    ctx2 = copy.copy(ctx)
    ctx2.furniture = L2
    ctx2.extra = bs.make_extra_blocked(L2, rg, ctx.yaw, ctx.home_clear, creep_back_m=back)
    ctx_nocreep = copy.copy(ctx2)
    ctx_nocreep.extra = bs.make_extra_blocked(L2, rg, ctx.yaw, ctx.home_clear)
    sA = select_bench_stance(tagged, world(), TASK_CFG, ctx_nocreep, cfg, say=quiet)
    sB = select_bench_stance(tagged, world(), TASK_CFG, ctx2, cfg, say=quiet)
    a, b = sA["report"]["runs"][0]["stance"], sB["report"]["runs"][0]["stance"]
    cb = bs.creep_blocked(L2, rg["footprint"], ctx.yaw, back)
    def clipped(st):
        cx, cy = int(round((st["xy"][0] - L2.origin[0]) / L2.res)), int(round((st["xy"][1] - L2.origin[1]) / L2.res))
        return bool(cb[cy, cx])
    print(f"    without the creep-in sweep the pick is {np.round(a['xy'], 3).tolist()} (creep path clipped: {clipped(a)}); with it {np.round(b['xy'], 3).tolist()} (clipped: {clipped(b)})")
    check("the stance whose creep-in path clips the post is rejected when the sweep is on, and the picked stance's path is clear", sB["ok"] and clipped(a) and not clipped(b) and tuple(np.round(a["xy"], 3)) != tuple(np.round(b["xy"], 3)))

    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
